def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    terms = []
    for i in range(n, -1, -1):
        coeff = coeffs[n - i]
        if coeff == 0:
            continue
        if i == 0:
            term = str(abs(coeff))
        elif i == 1:
            if abs(coeff) == 1:
                term = 'x' if coeff == 1 else '-x'
            else:
                term = f'{abs(coeff)}x'
        else:
            if abs(coeff) == 1:
                term = f'x^{i}' if coeff == 1 else f'-x^{i}'
            else:
                term = f'{abs(coeff)}x^{i}'
        if coeff < 0:
            term = '-' + term
        terms.append(term)
    return ''.join(terms)

def decode(encoded: str, original: str, message: str) -> str:
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    for e, o in zip(encoded, original):
        if e in mapping and mapping[e] != o:
            return "Failed"
        mapping[e] = o

    if len(mapping) != len(set(mapping.values())):
        return "Failed"

    decoded = []
    for char in message:
        if char in mapping:
            decoded.append(mapping[char])
        else:
            return "Failed"

    return ''.join(decoded)

