def minimum_students_to_leave(heights):
    n = len(heights)
    if n == 0:
        return 0

    # Find the maximum height position
    max_height_index = heights.index(max(heights))

    # Calculate the number of students to remove before the maximum height position
    left_remove = 0
    for i in range(max_height_index):
        if heights[i] >= heights[i + 1]:
            left_remove += 1

    # Calculate the number of students to remove after the maximum height position
    right_remove = 0
    for i in range(max_height_index, n - 1):
        if heights[i] <= heights[i + 1]:
            right_remove += 1

    # The total number of students to remove is the sum of left and right removals
    return left_remove + right_remove
